DROP INDEX "job_executions_status_started_at_idx";--> statement-breakpoint
DROP INDEX "keyword_discovery_attempted_idx";--> statement-breakpoint
ALTER TABLE "discovery_targets" ADD COLUMN "autocompleted" boolean DEFAULT false NOT NULL;--> statement-breakpoint
UPDATE "discovery_targets" t SET "autocompleted"=true FROM "keyword_autocomplete" a WHERE a.query_id=t.query_id AND a.stage='complete' AND t.kind='keyword';--> statement-breakpoint
CREATE INDEX "catalog_queries_scheduled_idx" ON "catalog_queries" USING btree ("next_due_at") WHERE "catalog_queries"."tier" <> 'stored';--> statement-breakpoint
CREATE INDEX "catalog_queries_requested_idx" ON "catalog_queries" USING btree ("last_requested_at") WHERE "catalog_queries"."last_requested_at" is not null;--> statement-breakpoint
CREATE INDEX "discovery_targets_keyword_cursor_idx" ON "discovery_targets" USING btree ("created_at","id") WHERE "discovery_targets"."kind" = 'keyword' and ("discovery_targets"."tracking" = 'tracked' or ("discovery_targets"."enabled" and "discovery_targets"."head_observed_at" is not null));--> statement-breakpoint
CREATE INDEX "discovery_targets_autocomplete_due_idx" ON "discovery_targets" USING btree ("popularity_score" DESC NULLS LAST,"query_id") WHERE "discovery_targets"."kind" = 'keyword' and "discovery_targets"."enabled" and "discovery_targets"."tracking" = 'tracked' and not "discovery_targets"."autocompleted";--> statement-breakpoint
CREATE INDEX "job_executions_started_at_idx" ON "job_executions" USING btree ("started_at");--> statement-breakpoint
CREATE INDEX "products_spapi_refresh_due_idx" ON "products" USING btree ((CASE WHEN "sp_api_fetched_at" IS NULL THEN '-infinity'::timestamp WHEN "root_category_bsr" < 200000 THEN "sp_api_fetched_at" + interval '86400 seconds' WHEN "root_category_bsr" < 500000 THEN "sp_api_fetched_at" + interval '259200 seconds' WHEN "root_category_bsr" < 1000000 THEN "sp_api_fetched_at" + interval '604800 seconds' WHEN "root_category_bsr" < 3000000 THEN "sp_api_fetched_at" + interval '1209600 seconds' ELSE "sp_api_fetched_at" + interval '2592000 seconds' END),"id") WHERE ("products"."is_merch_listing" AND "products"."amazon_listing_status" = 'active' AND "products"."root_category_bsr" IS NOT NULL);--> statement-breakpoint
CREATE INDEX "products_spapi_blindspot_due_idx" ON "products" USING btree ((CASE WHEN GREATEST("sp_api_fetched_at", "sp_api_resolved_at") IS NULL THEN '-infinity'::timestamp WHEN GREATEST("sp_api_fetched_at", "sp_api_resolved_at") + (CASE WHEN GREATEST("sp_api_fetched_at", "sp_api_resolved_at") < "created_at" + interval '259200 seconds' THEN interval '259200 seconds' ELSE interval '1209600 seconds' END) < "created_at" + interval '2592000 seconds' THEN GREATEST("sp_api_fetched_at", "sp_api_resolved_at") + (CASE WHEN GREATEST("sp_api_fetched_at", "sp_api_resolved_at") < "created_at" + interval '259200 seconds' THEN interval '259200 seconds' ELSE interval '1209600 seconds' END) ELSE GREATEST("sp_api_fetched_at", "sp_api_resolved_at") + interval '2592000 seconds' END),"created_at","id") WHERE ("products"."amazon_listing_status" = 'active' AND (("products"."is_merch_listing" AND "products"."root_category_bsr" IS NULL) OR (NOT "products"."is_merch_listing" AND "products"."sp_api_fetched_at" IS NULL AND "products"."sp_api_resolved_at" IS NULL)));--> statement-breakpoint
CREATE INDEX "products_keepa_refresh_due_idx" ON "products" USING btree ((COALESCE("keepa_fetched_at", '-infinity'::timestamp) + (CASE WHEN "root_category_bsr" < 50000 THEN interval '43200 seconds' WHEN "root_category_bsr" < 300000 THEN interval '86400 seconds' ELSE interval '604800 seconds' END))) WHERE ("products"."is_merch_listing" AND "products"."amazon_listing_status" = 'active' AND "products"."history_admission_state" = 'admitted' AND "products"."root_category_bsr" < 1000000);